/* questions.js - scored MCQ bank: Week 2 practice exam (case-based vignettes),
 * imported from BCEMP_Practice_Exams_3.html. Options are shuffled at display time.
 * Study aid only; verify against current guidelines and institutional protocols. */
window.BCEMP_QUESTIONS = [
  { id: "w2-001", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 58-year-old man with end-stage renal disease on hemodialysis is brought to the ED after collapsing in the waiting room. Per family he missed his last two dialysis sessions and has been weak with nausea. He is now pulseless; the monitor shows a wide-complex, organized rhythm at 40/min. CPR is initiated and a point-of-care metabolic panel is sent while the team runs through reversible causes. Which reversible cause is being addressed by giving IV calcium and sodium bicarbonate?",
    options: ["Hyperkalemia", "Hypovolemia", "Tension pneumothorax", "Thrombosis"], correctIndex: 0,
    rationale: "Hyperkalemia (an 'H') is treated with calcium (membrane stabilization) and bicarbonate/insulin-dextrose (shifting). The other reversible causes require different interventions (fluids, decompression, thrombolysis)." },
  { id: "w2-002", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 66-year-old woman is in cardiac arrest after a witnessed collapse. She remains in pulseless ventricular tachycardia after three defibrillations, two 1 mg doses of epinephrine, and a 300 mg IV dose of amiodarone. The team calls for a second antiarrhythmic. You check the automated cabinet and confirm amiodarone is on backorder with none remaining in the department. What do you recommend next?",
    options: ["Lidocaine 1-1.5 mg/kg IV", "Procainamide 50 mg/min", "Sotalol IV", "Adenosine 12 mg"], correctIndex: 0,
    rationale: "Lidocaine 1-1.5 mg/kg is the acceptable antiarrhythmic alternative to amiodarone in shock-refractory VF/pVT. Repeat lidocaine at 0.5-0.75 mg/kg is allowed." },
  { id: "w2-003", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 62-year-old is in cardiac arrest with pulseless electrical activity. High-quality CPR is ongoing and continuous waveform capnography has read 10-14 mmHg for several cycles. During the sixth rhythm check the end-tidal CO2 tracing abruptly rises and holds at 42 mmHg while compressions continue. What does this abrupt rise in end-tidal CO2 most likely indicate?",
    options: ["Return of spontaneous circulation", "Worsening arrest", "Need for more epinephrine", "Esophageal intubation"], correctIndex: 0,
    rationale: "An abrupt increase in ETCO2 (e.g., to >40 mmHg) suggests ROSC. Persistently low ETCO2 (<10) after 20 minutes of high-quality CPR portends poor prognosis and reflects poor perfusion." },
  { id: "w2-004", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 47-year-old woman is brought in after an intentional overdose; an empty bottle of metoprolol succinate is at the scene. She is profoundly bradycardic and hypotensive and has not responded to atropine 1 mg x3 or a 1 L crystalloid bolus. She is now peri-arrest. Which therapies target the underlying beta-blockade to improve inotropy and heart rate?",
    options: ["Glucagon and high-dose insulin/euglycemia", "Adenosine", "Amiodarone", "Nitroglycerin"], correctIndex: 0,
    rationale: "Glucagon raises cAMP independent of beta-receptors, and high-dose insulin therapy improves myocardial energetics—both used in beta-blocker toxicity with cardiovascular collapse." },
  { id: "w2-005", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 60-year-old man arrests in the ED. Despite six defibrillations, epinephrine every 3-5 minutes, amiodarone, and then lidocaine, he re-fibrillates within seconds of each shock. The attending asks whether any additional electrical strategy has been described for this presentation. This scenario is best described as:",
    options: ["Refractory ventricular fibrillation", "Asystole", "PEA", "Stable SVT"], correctIndex: 0,
    rationale: "Double sequential external defibrillation (two defibrillators nearly simultaneously) is an investigational strategy for refractory VF unresponsive to standard shocks; evidence remains evolving." },
  { id: "w2-006", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 71-year-old woman achieves return of spontaneous circulation after a witnessed VF arrest. She is intubated and off compressions with a palpable pulse, but remains hypotensive. The team needs to support her perfusion while identifying the arrest etiology. Which vasopressor is recommended to restore and maintain a MAP >=65 mmHg?",
    options: ["Norepinephrine (target MAP >=65 mmHg)", "Phenylephrine only", "Dopamine 20 mcg/kg/min", "Vasopressin monotherapy"], correctIndex: 0,
    rationale: "Post-arrest hypotension worsens outcomes; norepinephrine (or epinephrine) is titrated to maintain MAP >=65 mmHg and adequate cerebral perfusion, along with treating the underlying cause." },
  { id: "w2-007", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 55-year-old man is in an undifferentiated PEA arrest. He has no history of renal disease, calcium-channel-blocker use, or hypocalcemia, and the point-of-care potassium and ionized calcium are normal. A trainee asks whether to empirically push an ampule of calcium 'just in case.' Based on current evidence, routine calcium administration in this setting is associated with:",
    options: ["No benefit and possible harm", "Definite mortality benefit", "It only helps in asystole", "It shortens CPR duration"], correctIndex: 0,
    rationale: "Routine calcium in undifferentiated cardiac arrest showed no benefit and possible harm; it is reserved for specific indications (hyperkalemia, hypocalcemia, calcium-channel-blocker toxicity, hypermagnesemia)." },
  { id: "w2-008", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A code is called for an adult in VF. As you prepare medications, a nurse hands you a 1 mL vial labeled 'epinephrine 1 mg/mL' and asks whether this is the correct product to push intravenously during the arrest. Which epinephrine concentration is correct for IV/IO bolus during adult cardiac arrest?",
    options: ["0.1 mg/mL (1 mg in 10 mL)", "1 mg/mL", "0.5 mg/mL", "10 mg/mL"], correctIndex: 0,
    rationale: "IV/IO push epinephrine in arrest uses the 0.1 mg/mL concentration (1 mg in 10 mL). The 1 mg/mL concentration is for IM use (anaphylaxis); confusing them is a serious error." },
  { id: "w2-009", domain: "resus", difficulty: 2, tags: ["Resuscitation"],
    stem: "A 39-year-old woman on IV azithromycin and scheduled ondansetron for gastroenteritis suddenly develops a polymorphic wide-complex tachycardia that degenerates into cardiac arrest. Her pre-arrest ECG had shown a markedly prolonged QT. In this arrest, magnesium is specifically indicated because of:",
    options: ["Torsades or documented hypomagnesemia", "Any VF", "Bradycardia", "Hyperkalemia"], correctIndex: 0,
    rationale: "Magnesium is not routinely effective in VF but is specifically indicated for polymorphic VT/torsades or hypomagnesemia." },
  { id: "w2-010", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 68-year-old man who underwent drug-eluting stent placement two days ago presents with black tarry stools and lightheadedness. He takes aspirin 81 mg and ticagrelor 90 mg twice daily. He appears pale and diaphoretic. What is the immediate priority in managing this patient?",
    options: ["Assess bleeding severity and weigh holding antiplatelets vs. thrombotic risk", "Continue and add a third antiplatelet", "Give vitamin K", "Start thrombolytics"], correctIndex: 0,
    rationale: "Management balances active bleeding against stent thrombosis risk; decisions on holding/reducing antiplatelet therapy are individualized with cardiology, alongside resuscitation and source control. Platelet transfusion may be considered for life-threatening bleeding." },
  { id: "w2-011", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 61-year-old man with an anterior STEMI is en route to the cath lab for primary PCI. He is intubated and cannot take oral medications, and the interventionalist wants intravenous P2Y12 inhibition available during the procedure. IV cangrelor is selected. Which property makes cangrelor suited to this bridging role?",
    options: ["Is IV with rapid onset/offset (platelet function recovers ~60 min after stopping)", "Is an oral prodrug", "Has a long half-life", "Is irreversible for weeks"], correctIndex: 0,
    rationale: "Cangrelor is an IV, reversible P2Y12 inhibitor with rapid onset and offset (function recovers ~60 minutes after discontinuation), useful for PCI bridging when oral agents cannot be used." },
  { id: "w2-012", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 34-year-old man who used cocaine an hour ago presents with crushing substernal chest pain. He is anxious and hypertensive; ECG shows 2 mm of ST elevation in the anterior leads. A resident asks about starting a beta-blocker for rate and blood pressure control. Which medication class should generally be avoided in this presentation?",
    options: ["Non-selective beta-blockers (unopposed alpha stimulation)", "Benzodiazepines", "Nitroglycerin", "Aspirin"], correctIndex: 0,
    rationale: "Non-selective beta-blockers can cause unopposed alpha-mediated vasoconstriction/coronary spasm in cocaine toxicity. Benzodiazepines, nitrates, and aspirin are preferred; treat with calcium channel blockers if needed." },
  { id: "w2-013", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 57-year-old man presents with an inferior STEMI. The nearest PCI-capable center is more than 120 minutes away, so the team elects fibrinolysis with weight-based tenecteplase after confirming no contraindications. They are finalizing the adjunctive regimen. To reduce reocclusion, which adjunctive anticoagulant is recommended alongside antiplatelet therapy?",
    options: ["Enoxaparin (or UFH) as adjunct", "No anticoagulation", "Warfarin alone", "Aspirin as anticoagulant"], correctIndex: 0,
    rationale: "Fibrinolysis for STEMI is accompanied by anticoagulation (enoxaparin or UFH) plus antiplatelet therapy to reduce reocclusion. Enoxaparin dosing is age-adjusted (no bolus if >=75 years)." },
  { id: "w2-014", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 49-year-old woman presents with atypical, brief chest discomfort that has resolved. Her ECG is nonischemic and she has no prior cardiac history. A high-sensitivity troponin is undetectable at presentation and remains very low and unchanged on the 2-hour draw. This pattern supports which of the following?",
    options: ["Rapid rule-out of myocardial infarction in appropriate patients", "Immediate cath lab activation", "Fibrinolysis", "Definite STEMI"], correctIndex: 0,
    rationale: "High-sensitivity troponin algorithms (0/1h or 0/2h) allow rapid rule-out of MI when values are very low and stable, in conjunction with clinical assessment/ECG." },
  { id: "w2-015", domain: "cv", difficulty: 2, tags: ["ACS"],
    stem: "A 63-year-old man with a known ejection fraction of 20% presents in cardiogenic shock. He is cool and mottled with poor urine output despite adequate filling pressures on bedside ultrasound. Lactate is rising. Which agent is appropriate to improve cardiac output?",
    options: ["Dobutamine or milrinone", "Phenylephrine", "Esmolol", "Metoprolol"], correctIndex: 0,
    rationale: "Cardiogenic shock/low-output heart failure benefits from inotropic support (dobutamine, milrinone). Beta-blockers are contraindicated in acute decompensation; pure vasoconstrictors don't improve output." },
  { id: "w2-016", domain: "cv", difficulty: 2, tags: ["Arrhythmias"],
    stem: "A 55-year-old woman presents with palpitations and a wide-complex tachycardia at 190/min. She is diaphoretic, confused, and hypotensive with cool extremities. What is the most appropriate immediate intervention?",
    options: ["Synchronized cardioversion", "Adenosine 6 mg", "Amiodarone infusion over 10 min", "Diltiazem push"], correctIndex: 0,
    rationale: "Unstable tachyarrhythmias (hypotension, altered mental status, ischemia, shock) require immediate synchronized cardioversion, not pharmacologic first-line therapy." },
  { id: "w2-017", domain: "cv", difficulty: 2, tags: ["Arrhythmias"],
    stem: "A 60-year-old man has a sustained monomorphic ventricular tachycardia at 160/min. He is alert with a normal blood pressure and no chest pain or ischemic ECG changes, and known preserved LV function. The team elects pharmacologic management. What is the correct amiodarone regimen for this stable VT?",
    options: ["150 mg IV over 10 minutes, may repeat", "300 mg IV push", "6 mg rapid push", "1 mg/min without a load"], correctIndex: 0,
    rationale: "For stable VT, amiodarone 150 mg IV over 10 minutes (repeatable) followed by an infusion (1 mg/min x6h then 0.5 mg/min) is standard. The 300 mg push is for pulseless VT/VF." },
  { id: "w2-018", domain: "cv", difficulty: 2, tags: ["Arrhythmias"],
    stem: "A 74-year-old man on digoxin for heart failure presents with nausea, blurred yellow vision, and confusion. Telemetry shows an unusual rhythm in which the QRS axis alternates beat-to-beat. Which arrhythmia is characteristic of this toxicity?",
    options: ["Bidirectional ventricular tachycardia", "Atrial fibrillation", "First-degree AV block", "Sinus tachycardia"], correctIndex: 0,
    rationale: "Bidirectional VT is characteristic of digoxin toxicity. Other findings include atrial tachycardia with block, junctional rhythms, and various blocks; hyperkalemia predicts severity." },
  { id: "w2-019", domain: "cv", difficulty: 2, tags: ["Arrhythmias"],
    stem: "A 58-year-old woman with symptomatic atrial flutter is given ibutilide in an attempt at pharmacologic cardioversion. The pharmacist is asked about post-administration monitoring and bedside precautions. What is the most important monitoring concern, and what should be immediately available?",
    options: ["QT prolongation and torsades (monitor 4+ hours, have magnesium ready)", "Hyperkalemia", "Hepatotoxicity", "Bronchospasm"], correctIndex: 0,
    rationale: "Ibutilide prolongs the QT and can cause torsades; monitor ECG for at least 4 hours after administration and ensure magnesium/defibrillation availability. Avoid with hypokalemia/hypomagnesemia or prolonged QT." },
  { id: "w2-020", domain: "cv", difficulty: 2, tags: ["Arrhythmias"],
    stem: "A 29-year-old man with known Wolff-Parkinson-White presents with an irregular, wide-complex tachycardia with rates up to 240/min, consistent with pre-excited atrial fibrillation. He is currently maintaining his blood pressure. Which agent is preferred for rate/rhythm control here?",
    options: ["Procainamide", "Diltiazem", "Adenosine", "Digoxin"], correctIndex: 0,
    rationale: "Procainamide (or ibutilide) is preferred in pre-excited AF; AV nodal blockers (adenosine, diltiazem, beta-blockers, digoxin) can accelerate accessory pathway conduction and precipitate VF." },
  { id: "w2-021", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "A 72-year-old man presents with acute right-sided weakness and aphasia that began 3 hours ago (NIHSS 12). Non-contrast CT shows no hemorrhage, and CT perfusion suggests salvageable penumbra. The team is confirming thrombolysis eligibility. Within what window is IV alteplase standard, with select patients extended by advanced imaging?",
    options: ["4.5 hours (with advanced imaging selection extending some cases)", "24 hours for all", "1 hour only", "12 hours routinely"], correctIndex: 0,
    rationale: "IV alteplase is standard within 4.5 hours; select patients may benefit with advanced imaging (WAKE-UP/EXTEND). Mechanical thrombectomy can extend to 24 hours in select large-vessel occlusion patients with favorable imaging." },
  { id: "w2-022", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "A 65-year-old man received IV alteplase for an acute ischemic stroke 2 hours ago. His prior aspirin has worn off, and the team asks when antiplatelet therapy can be safely resumed. After thrombolysis, antithrombotic therapy should generally be withheld for:",
    options: ["At least 24 hours (after repeat imaging rules out hemorrhage)", "No delay", "1 hour", "72 hours minimum"], correctIndex: 0,
    rationale: "Antithrombotics are typically withheld for 24 hours post-thrombolysis, with repeat neuroimaging to exclude hemorrhage before starting antiplatelet/anticoagulant therapy." },
  { id: "w2-023", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "A 70-year-old man on dabigatran for atrial fibrillation (last dose about 10 hours ago) presents with an acute ischemic stroke. He is otherwise within the thrombolysis window with no hemorrhage on CT, but his recent DOAC use is a concern. Which option can enable thrombolysis in this DOAC-anticoagulated patient?",
    options: ["Reverse with idarucizumab, then consider thrombolysis", "Give alteplase immediately regardless", "Give andexanet alfa", "Proceed without concern"], correctIndex: 0,
    rationale: "Recent DOAC use is a relative contraindication to thrombolysis; idarucizumab can reverse dabigatran to permit thrombolysis in select cases. Thrombectomy avoids this bleeding concern." },
  { id: "w2-024", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "Your comprehensive stroke center is revising its thrombolytic protocol and the P&T subcommittee is comparing tenecteplase 0.25 mg/kg with the standard alteplase infusion for acute ischemic stroke. What is a key practical advantage of tenecteplase in this setting?",
    options: ["Is given as a single IV bolus with comparable efficacy", "Requires a prolonged infusion", "Has no bleeding risk", "Reverses itself"], correctIndex: 0,
    rationale: "Tenecteplase 0.25 mg/kg single bolus is easier to administer than the alteplase infusion and shows comparable (possibly better for large-vessel occlusion) outcomes, and is used in many stroke centers." },
  { id: "w2-025", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "A 68-year-old man undergoes mechanical thrombectomy for a large-vessel occlusion with complete reperfusion. In the neuro-ICU his blood pressure is now elevated, and the team is deciding on a post-procedure target. Regarding post-reperfusion blood pressure, the reasonable approach is:",
    options: ["Lower BP (e.g., <180/105 or individualized) to reduce reperfusion injury", "No BP control", "Keep SBP >200", "Permissive hypertension always"], correctIndex: 0,
    rationale: "After successful reperfusion, more intensive BP control (often <180/105, sometimes lower) is used to limit reperfusion injury/hemorrhage, individualized to reperfusion status." },
  { id: "w2-026", domain: "neuro", difficulty: 2, tags: ["Stroke"],
    stem: "A 77-year-old woman on warfarin presents with acute headache and a dense hemiparesis; CT shows a large intraparenchymal hemorrhage. She receives 4-factor PCC and IV vitamin K, and the team plans a follow-up coagulation panel. After reversal, what INR goal confirms adequate correction?",
    options: ["<1.4", "<2.0", "<3.0", "Normalization not needed"], correctIndex: 0,
    rationale: "For warfarin-associated intracranial hemorrhage, rapid reversal targets an INR <1.4 using 4-factor PCC plus IV vitamin K, with recheck to confirm sustained reversal." },
  { id: "w2-027", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 62-year-old man in septic shock from pyelonephritis has received fluids and empiric antibiotics. His initial lactate was 6 mmol/L; the team draws a repeat value at 2 hours to gauge his response. Serial lactate measurement is used primarily to:",
    options: ["Guide adequacy of resuscitation (aim to normalize/clear lactate)", "Diagnose the infection source", "Dose antibiotics", "Determine antibiotic duration"], correctIndex: 0,
    rationale: "Serial lactate measurement guides resuscitation adequacy; a strategy of lactate clearance/normalization is recommended to assess perfusion and response to therapy." },
  { id: "w2-028", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 60-year-old man with septic shock is being resuscitated. He has received 30 mL/kg of crystalloid and remains on norepinephrine. A colleague suggests adding hydroxyethyl starch to limit further crystalloid volume. What is the correct guidance regarding hydroxyethyl-starch colloids in sepsis?",
    options: ["They should be avoided due to AKI and mortality risk", "They are first-line", "They are preferred over crystalloids", "They reduce coagulopathy"], correctIndex: 0,
    rationale: "Hydroxyethyl starches increase AKI and mortality risk in sepsis and should be avoided; crystalloids (balanced preferred) are the resuscitation fluid of choice, with albumin as an adjunct in select cases." },
  { id: "w2-029", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 44-year-old man presents with septic shock and diffuse abdominal tenderness; a perforated viscus is suspected. His chart documents a prior anaphylactic reaction to penicillin (angioedema and hypotension). Which empiric regimen provides broad coverage while avoiding cross-reactive beta-lactams?",
    options: ["Aztreonam + metronidazole + vancomycin", "Piperacillin-tazobactam", "Meropenem alone", "Ceftriaxone + metronidazole"], correctIndex: 0,
    rationale: "For true beta-lactam anaphylaxis, aztreonam (gram-negatives) plus metronidazole (anaerobes) plus vancomycin (gram-positives) provides broad coverage while avoiding cross-reactive beta-lactams." },
  { id: "w2-030", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 70-year-old woman in septic shock is on norepinephrine 0.4 mcg/kg/min with a MAP that remains 58. Vasopressin is added at a fixed 0.03 units/min. A nurse asks whether the vasopressin can be titrated up like the norepinephrine. Vasopressin should generally NOT be managed in which of the following ways?",
    options: ["Titrated up like catecholamines", "Used with norepinephrine", "Given at 0.03 units/min", "Considered catecholamine-sparing"], correctIndex: 0,
    rationale: "Vasopressin is given at a fixed low dose (typically 0.03 units/min) and generally not titrated upward due to ischemic risks; it is added to norepinephrine as a catecholamine-sparing agent." },
  { id: "w2-031", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 55-year-old man presents with septic shock, a rigid abdomen, and free air under the diaphragm on imaging, consistent with a perforated viscus. Empiric antibiotics are being selected while surgery is consulted. Which empiric regimen best covers the expected gram-negative, anaerobic, and enterococcal pathogens?",
    options: ["Piperacillin-tazobactam (covers gram-negatives, anaerobes, enterococci)", "Vancomycin alone", "Azithromycin", "Ceftriaxone alone"], correctIndex: 0,
    rationale: "Intra-abdominal sepsis requires coverage of gram-negatives and anaerobes; piperacillin-tazobactam or a carbapenem (or ceftriaxone + metronidazole) are appropriate, with source control." },
  { id: "w2-032", domain: "resus", difficulty: 2, tags: ["Sepsis"],
    stem: "A 70-year-old man in septic shock has received 30 mL/kg of crystalloid and remains hypotensive. The team debates whether additional fluid will help or cause harm and wants an objective measure of fluid responsiveness. Which assessment best predicts whether additional fluid will improve cardiac output?",
    options: ["Passive leg raise or pulse pressure variation", "Static CVP", "Blood pressure alone", "Urine output over 24h"], correctIndex: 0,
    rationale: "Dynamic measures (passive leg raise, pulse pressure/stroke volume variation) better predict fluid responsiveness than static CVP, which correlates poorly with volume status." },
  { id: "w2-033", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 60-year-old man with gram-negative bacteremia is started on an aminoglycoside. Pharmacy recommends an extended-interval (once-daily) dosing strategy and explains the rationale to the team. Extended-interval aminoglycoside dosing leverages which pharmacodynamic property?",
    options: ["Concentration-dependent killing and post-antibiotic effect", "Time-dependent killing", "Renal protection guarantee", "Lack of monitoring need"], correctIndex: 0,
    rationale: "Aminoglycosides exhibit concentration-dependent killing and a post-antibiotic effect, supporting extended-interval dosing to maximize peak/MIC while reducing nephro/ototoxicity. Monitoring is still required." },
  { id: "w2-034", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 68-year-old man with CrCl 35 mL/min is admitted with sepsis and started on a broad-spectrum beta-lactam. On hospital day 3 he develops confusion, myoclonic jerks, and a non-convulsive seizure on EEG. Which agent is the most likely culprit if it was not renally dose-adjusted?",
    options: ["Cefepime", "Azithromycin", "Doxycycline", "Linezolid"], correctIndex: 0,
    rationale: "Cefepime accumulates in renal impairment and can cause neurotoxicity (encephalopathy, myoclonus, non-convulsive status epilepticus); renal dose adjustment is essential." },
  { id: "w2-035", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 40-year-old man presents about 6 hours after a cat bite to the dorsum of the hand. There is now spreading erythema, warmth, and tenderness with early purulent drainage. Which oral agent best covers the expected pathogens, including Pasteurella?",
    options: ["Amoxicillin-clavulanate", "Cephalexin alone", "Clindamycin alone", "Azithromycin"], correctIndex: 0,
    rationale: "Amoxicillin-clavulanate covers Pasteurella multocida, streptococci, staphylococci, and anaerobes from animal bites. Cephalexin and clindamycin alone miss Pasteurella; combine agents if penicillin-allergic." },
  { id: "w2-036", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 55-year-old woman with fever and flank pain is diagnosed with pyelonephritis and is being prepared for discharge on oral therapy. A resident writes for nitrofurantoin. Which of these agents is inappropriate for treating her pyelonephritis?",
    options: ["Nitrofurantoin", "Ciprofloxacin", "Ceftriaxone", "Trimethoprim-sulfamethoxazole"], correctIndex: 0,
    rationale: "Nitrofurantoin concentrates in the bladder/urine but does NOT achieve therapeutic tissue or serum levels, so it must not be used for pyelonephritis (a renal parenchymal/tissue infection). Ciprofloxacin, ceftriaxone, and trimethoprim-sulfamethoxazole (if susceptible) are appropriate options." },
  { id: "w2-037", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 62-year-old man is receiving his first vancomycin dose, infused over 30 minutes, when he develops flushing and erythema of the face, neck, and upper torso. He has no wheeze, hypotension, or throat tightness. What is the mechanism, and what adjustment is appropriate?",
    options: ["Rapid infusion-related histamine release (infuse over >=1 hour)", "IgE-mediated anaphylaxis", "Renal failure", "Bacterial endotoxin"], correctIndex: 0,
    rationale: "Vancomycin flushing reaction (formerly 'red man syndrome') results from rate-related non-immune histamine release; slowing the infusion (>=60 min) and antihistamine pretreatment mitigate it. It is not a true allergy." },
  { id: "w2-038", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "An 80-year-old nursing-home resident presents with profuse diarrhea, abdominal distension, and hypotension. Stool is positive for C. difficile toxin, and imaging shows colonic dilation with an ileus. What is the appropriate initial therapy for this fulminant C. difficile presentation?",
    options: ["Oral vancomycin (high-dose) +/- IV metronidazole", "Oral metronidazole alone", "IV vancomycin", "Fidaxomicin only if mild"], correctIndex: 0,
    rationale: "Fulminant C. difficile (hypotension, ileus, megacolon) is treated with high-dose oral (or per rectum) vancomycin plus IV metronidazole; surgical consultation is warranted. IV vancomycin does not treat colonic C. diff." },
  { id: "w2-039", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 45-year-old man on chronic sertraline is started on linezolid for a resistant gram-positive infection. The pharmacist reviews the profile for interactions before the first dose. What adverse drug interaction should you counsel the team about?",
    options: ["Serotonin syndrome (linezolid is a weak MAO inhibitor)", "Hyperkalemia", "QT prolongation only", "Nephrotoxicity"], correctIndex: 0,
    rationale: "Linezolid is a weak monoamine oxidase inhibitor; combining with serotonergic agents (SSRIs, SNRIs, meperidine) risks serotonin syndrome. Weigh risks/benefits and monitor closely." },
  { id: "w2-040", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 58-year-old man with diabetes presents with a deep, foul-smelling plantar foot ulcer probing to bone, fever, and hypotension. A prior wound culture grew MRSA. Which empiric regimen is appropriate?",
    options: ["Broad gram-negative/anaerobic coverage plus an anti-MRSA agent", "A narrow gram-positive agent only", "An antifungal only", "Nitrofurantoin"], correctIndex: 0,
    rationale: "Severe diabetic foot infections require broad coverage (gram-positives including MRSA if risk factors, gram-negatives, and anaerobes), e.g., vancomycin + piperacillin-tazobactam, plus source control." },
  { id: "w2-041", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 30-year-old man is brought in agitated and flushed with dry skin, dilated pupils, urinary retention, and absent bowel sounds; he is picking at the air and mumbling. He reportedly ingested a large amount of diphenhydramine. His QRS is normal. Which antidote may reverse the central anticholinergic delirium, used cautiously?",
    options: ["Physostigmine (used cautiously)", "Naloxone", "Flumazenil", "Pralidoxime"], correctIndex: 0,
    rationale: "Physostigmine, an acetylcholinesterase inhibitor, can reverse central anticholinergic delirium but is used cautiously (contraindicated with TCA/wide QRS due to seizure/asystole risk). Benzodiazepines control agitation." },
  { id: "w2-042", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 26-year-old is found unresponsive with pinpoint pupils and a respiratory rate of 4; a presumed opioid overdose. The team wants to restore adequate ventilation while minimizing precipitated withdrawal. How should naloxone be dosed to achieve this goal?",
    options: ["0.04-0.4 mg titrated to respiration", "2 mg IV push immediately in all", "10 mg IM", "0.001 mg"], correctIndex: 0,
    rationale: "Titrating naloxone (e.g., 0.04-0.4 mg, repeat/escalate as needed) targets adequate respiration while minimizing precipitated withdrawal. Larger doses may be needed for potent synthetic opioids (fentanyl analogs)." },
  { id: "w2-043", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 33-year-old responds to naloxone after a methadone overdose and becomes alert. About 40 minutes later he becomes somnolent again with a falling respiratory rate. What explains this recurrence, and what may be required?",
    options: ["Re-sedation as naloxone wears off (may need infusion)", "Permanent reversal", "Hepatotoxicity", "Hyperkalemia"], correctIndex: 0,
    rationale: "Naloxone has a shorter duration than many opioids (methadone, extended-release products); re-sedation/respiratory depression can recur, requiring redosing or a continuous naloxone infusion and prolonged monitoring." },
  { id: "w2-044", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 71-year-old woman on glipizide is brought in obtunded with a fingerstick of 32 mg/dL. She is given IV dextrose and improves, but over the next several hours she has repeated symptomatic hypoglycemic episodes despite additional dextrose. Which agent provides durable control by suppressing insulin release?",
    options: ["Octreotide", "Glucagon infusion", "Insulin", "Fomepizole"], correctIndex: 0,
    rationale: "Octreotide suppresses insulin release and prevents recurrent hypoglycemia in sulfonylurea overdose, reducing the need for repeated dextrose boluses. Glucagon is short-lived and depletes glycogen." },
  { id: "w2-045", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 22-year-old woman presents after ingesting ethylene glycol. She has a severe high anion-gap metabolic acidosis, and urinalysis shows calcium oxalate crystals. Fomepizole is started and dialysis is being arranged. Which vitamin cofactors help shunt metabolism toward non-toxic products?",
    options: ["Thiamine and pyridoxine", "Vitamin K and folate", "Vitamin C only", "Niacin"], correctIndex: 0,
    rationale: "Thiamine and pyridoxine are cofactors that shunt glyoxylic acid toward non-toxic metabolites in ethylene glycol poisoning; folate/folinic acid is used similarly in methanol toxicity. Fomepizole and dialysis are primary." },
  { id: "w2-046", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 19-year-old ingested a large amount of a sustained-release verapamil formulation about 90 minutes ago and is currently asymptomatic. Because the product is enteric-coated, activated charcoal is unlikely to fully bind the pellets. Which decontamination method is most appropriate?",
    options: ["Whole bowel irrigation with polyethylene glycol", "Syrup of ipecac to induce emesis", "Repeat-dose activated charcoal alone", "Gastric lavage"], correctIndex: 0,
    rationale: "Whole bowel irrigation with polyethylene glycol mechanically flushes the GI tract and is preferred for sustained-release/enteric-coated products, agents charcoal binds poorly (iron, lithium), and body packers. Ipecac is obsolete; charcoal poorly binds these pellets; gastric lavage has a very limited role." },
  { id: "w2-047", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A medical toxicologist is teaching a session on gastrointestinal decontamination and its limitations. Activated charcoal adsorbs many organic compounds but has well-known exceptions among small ionic or metallic substances and certain other agents. Which of the following ingestions is LEAST likely to be adsorbed by activated charcoal?",
    options: ["Lithium", "Aspirin", "Carbamazepine", "Phenobarbital"], correctIndex: 0,
    rationale: "Activated charcoal poorly binds small ionic/metallic substances such as lithium, iron, lead, potassium, alcohols, and hydrocarbons. It binds many organic drugs like aspirin, carbamazepine, and phenobarbital well." },
  { id: "w2-048", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 24-year-old ingested extended-release verapamil and is now bradycardic and hypotensive despite IV calcium and escalating vasopressors. The team looks for additional therapy to improve contractility. Which therapy improves inotropy via enhanced myocardial glucose utilization?",
    options: ["High-dose insulin euglycemia therapy", "Adenosine", "Amiodarone", "Nitroprusside"], correctIndex: 0,
    rationale: "High-dose insulin (with dextrose to maintain euglycemia) improves myocardial contractility and glucose utilization in calcium channel blocker toxicity; lipid emulsion is a rescue adjunct." },
  { id: "w2-049", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 55-year-old man is pulled from a house fire and has headache, confusion, and chest pain. Pulse oximetry reads normal, but a co-oximeter returns an elevated carboxyhemoglobin. Beyond removing him from exposure, what is the appropriate treatment?",
    options: ["100% oxygen (consider hyperbaric oxygen)", "Methylene blue", "Deferoxamine", "Naloxone"], correctIndex: 0,
    rationale: "High-flow 100% oxygen accelerates CO elimination; hyperbaric oxygen is considered for severe poisoning (neurologic deficits, cardiac ischemia, pregnancy, high COHb) to reduce delayed neurologic sequelae. Pulse oximetry is falsely normal." },
  { id: "w2-050", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 46-year-old man started on dapsone develops cyanosis and dyspnea. His oxygen saturation is stuck near 85% and does not improve with 100% oxygen; a blood sample drawn appears chocolate-brown. What is the characteristic finding in this condition?",
    options: ["Cyanosis with 'saturation gap' unresponsive to oxygen; chocolate-brown blood", "Bright red blood", "Normal pulse oximetry always", "Immediate response to oxygen"], correctIndex: 0,
    rationale: "Methemoglobinemia causes cyanosis with a gap between pulse oximetry (often ~85%) and calculated SaO2, unresponsive to supplemental oxygen; blood appears chocolate-brown. Methylene blue is the antidote (unless G6PD deficient)." },
  { id: "w2-051", domain: "resus", difficulty: 2, tags: ["RSI"],
    stem: "A 48-year-old presents with a severe high anion-gap metabolic acidosis of uncertain cause. He is markedly tachypneic and compensating, and the team is considering intubation for airway protection. Why is RSI-associated apnea especially dangerous in this patient?",
    options: ["Apnea can worsen acidosis; consider awake technique/pre-oxygenation and avoid prolonged apnea", "Paralytics fix acidosis", "Sedatives correct pH", "Acidosis has no effect"], correctIndex: 0,
    rationale: "Patients compensating for severe metabolic acidosis with tachypnea can deteriorate rapidly if apneic during RSI; strategies include optimizing pre-intubation status, minimizing apnea time, and possibly awake intubation." },
  { id: "w2-052", domain: "resus", difficulty: 2, tags: ["RSI"],
    stem: "A 33-year-old man requires emergent intubation for a decreased level of consciousness. His point-of-care potassium is markedly elevated with peaked T waves on the monitor. Which paralytic must be avoided due to hyperkalemia risk?",
    options: ["Succinylcholine", "Rocuronium", "Vecuronium", "Cisatracurium"], correctIndex: 0,
    rationale: "Succinylcholine has a short duration (~5-10 min), allowing quicker return of neurologic exam; however, contraindications (hyperkalemia risk) may favor rocuronium (reversible with sugammadex)." },
  { id: "w2-053", domain: "resus", difficulty: 2, tags: ["RSI"],
    stem: "A 40-year-old actively seizing patient is given etomidate for induction during rapid-sequence intubation. Immediately after the push, the team notices brief, jerking movements of the limbs. What is the most likely explanation for these movements?",
    options: ["Myoclonus that can be confused with seizure activity", "Prolonged paralysis", "Hyperkalemia", "Bronchospasm"], correctIndex: 0,
    rationale: "Etomidate can cause myoclonic movements that may be mistaken for seizures; it is otherwise hemodynamically stable. It does not have anticonvulsant properties." },
  { id: "w2-054", domain: "resus", difficulty: 2, tags: ["RSI"],
    stem: "A 25-year-old with a severe traumatic brain injury and hypotension requires rapid-sequence intubation. A resident hesitates, worried that ketamine will raise intracranial pressure. What is the current understanding of ketamine use in head injury?",
    options: ["Refuted; it is now considered acceptable and may support hemodynamics", "Confirmed as absolutely contraindicated", "Replaced by requiring intubation first", "Related to hepatotoxicity"], correctIndex: 0,
    rationale: "Concerns about ketamine raising ICP have been largely refuted; it is now considered acceptable for RSI in head injury and is favored in hypotension due to its hemodynamic support." },
  { id: "w2-055", domain: "resus", difficulty: 2, tags: ["RSI"],
    stem: "A 60-year-old was intubated 10 minutes ago using etomidate and rocuronium and is now on the ventilator. He intermittently grimaces and is tachycardic, but has received no additional medication since intubation. What is the priority regarding ongoing analgosedation?",
    options: ["Adequate analgesia first, then sedation (analgesia-first strategy)", "Deep sedation without analgesia", "Paralysis maintained routinely", "Sedation only, no analgesia"], correctIndex: 0,
    rationale: "An analgesia-first (analgosedation) approach addresses pain (a major cause of agitation) before/along with sedation, often reducing overall sedative needs and improving outcomes." },
  { id: "w2-056", domain: "neuro", difficulty: 2, tags: ["Status Epilepticus"],
    stem: "A prehospital crew reaches a patient who has been convulsing continuously for about 8 minutes. They are unable to establish IV access after two attempts. Why is IM midazolam preferred over waiting to establish IV access for lorazepam?",
    options: ["It can be given without IV access, with comparable efficacy", "It lasts longer", "It has no respiratory depression", "It is an antiarrhythmic"], correctIndex: 0,
    rationale: "The RAMPART trial showed IM midazolam is at least as effective as IV lorazepam for prehospital status epilepticus and can be given rapidly without IV access, reducing time to treatment." },
  { id: "w2-057", domain: "neuro", difficulty: 2, tags: ["Status Epilepticus"],
    stem: "A 28-year-old with known hepatic disease and a suspected mitochondrial disorder is in status epilepticus that has not responded to adequate benzodiazepine dosing. The team is choosing a second-line agent. Which second-line agent should be used cautiously or avoided in this patient?",
    options: ["Valproate", "Levetiracetam", "Fosphenytoin", "Lacosamide"], correctIndex: 0,
    rationale: "Valproate is relatively contraindicated in hepatic disease, pregnancy, and mitochondrial disorders (e.g., POLG mutations) due to hepatotoxicity/hyperammonemia risk. Levetiracetam, fosphenytoin, or lacosamide are safer second-line choices here." },
  { id: "w2-058", domain: "neuro", difficulty: 2, tags: ["Status Epilepticus"],
    stem: "A 45-year-old man with alcohol use disorder presents actively seizing. Adequate benzodiazepines are given but seizures persist. Basic labs return a critically low sodium. What is the most important intervention?",
    options: ["Correct the hyponatremia (treat the underlying cause)", "More benzodiazepines only", "Immediate phenytoin", "Ignore the sodium"], correctIndex: 0,
    rationale: "Seizures due to a metabolic cause (severe hyponatremia) require correcting the underlying abnormality (hypertonic saline for symptomatic severe hyponatremia); anticonvulsants alone will be ineffective." },
  { id: "w2-059", domain: "neuro", difficulty: 2, tags: ["Status Epilepticus"],
    stem: "A nurse is preparing an IV phenytoin infusion for a patient in status epilepticus. The only running line currently has dextrose 5% infusing, and she asks about compatibility before piggybacking the phenytoin. Why must phenytoin not be mixed with dextrose-containing solutions?",
    options: ["Precipitates in dextrose (use normal saline)", "Loses potency", "Becomes toxic", "Turns to fosphenytoin"], correctIndex: 0,
    rationale: "Phenytoin precipitates in dextrose solutions and must be diluted in normal saline with an in-line filter. Fosphenytoin is more compatible and less irritating." },
  { id: "w2-060", domain: "trauma", difficulty: 2, tags: ["Trauma"],
    stem: "A 68-year-old man on warfarin is brought in after a motor-vehicle collision in hemorrhagic shock, with a positive FAST exam. Massive transfusion is initiated along with tranexamic acid. Along with balanced transfusion and TXA, what is the appropriate early reversal?",
    options: ["4-factor PCC and vitamin K along with blood products", "FFP only, slowly", "Vitamin K PO only", "No reversal until INR resolves"], correctIndex: 0,
    rationale: "Traumatic hemorrhage on warfarin warrants rapid reversal with 4-factor PCC plus IV vitamin K alongside balanced transfusion and TXA (if within 3 hours), and source control." },
  { id: "w2-061", domain: "trauma", difficulty: 2, tags: ["Trauma"],
    stem: "A trauma patient in hemorrhagic shock has received six units of packed red cells. The monitor now shows a widened QRS and worsening hypotension, and the ionized calcium is low. Why is this hypocalcemia clinically important?",
    options: ["Impairs coagulation and cardiac contractility", "Improves clotting", "Has no clinical impact", "Only affects potassium"], correctIndex: 0,
    rationale: "Citrate in blood products chelates calcium; ionized hypocalcemia worsens coagulopathy and myocardial function ('lethal diamond' includes hypocalcemia). Empiric calcium is often given during massive transfusion." },
  { id: "w2-062", domain: "trauma", difficulty: 2, tags: ["Trauma"],
    stem: "A 30-year-old man in hemorrhagic shock from blunt abdominal trauma arrives about 40 minutes after injury. The trauma team asks whether tranexamic acid is beneficial at this point. Based on CRASH-2, early TXA administration (within 3 hours):",
    options: ["Reduced mortality when given early (within 3 hours)", "Increased mortality overall", "Had no effect on bleeding", "Only helped after 6 hours"], correctIndex: 0,
    rationale: "CRASH-2 showed reduced all-cause and bleeding-related mortality with early TXA (within 3 hours of injury); administration after 3 hours may increase bleeding-related death." },
  { id: "w2-063", domain: "trauma", difficulty: 2, tags: ["Trauma"],
    stem: "A 62-year-old man on apixaban is brought in after a fall with an unstable pelvic fracture and hemorrhagic shock. The team checks whether andexanet alfa is available while resuscitation proceeds. What is the appropriate reversal approach?",
    options: ["Andexanet alfa or 4-factor PCC plus resuscitation", "Idarucizumab", "Protamine", "Vitamin K only"], correctIndex: 0,
    rationale: "Factor Xa inhibitor (apixaban) reversal uses andexanet alfa or, if unavailable, 4-factor PCC, along with balanced transfusion, TXA, and definitive hemorrhage control." },
  { id: "w2-064", domain: "trauma", difficulty: 2, tags: ["Trauma"],
    stem: "A 25-year-old with a severe traumatic brain injury has an intracranial pressure of 28 mmHg and early signs of herniation. A resident asks about prophylactically hyperventilating him to a PaCO2 of 25 for the next several hours. What is the correct guidance on hyperventilation here?",
    options: ["Used only briefly as a temporizing measure (avoid prophylactic/prolonged use)", "A routine long-term therapy", "Contraindicated always", "First-line before osmotherapy"], correctIndex: 0,
    rationale: "Hyperventilation transiently lowers ICP via cerebral vasoconstriction but risks ischemia; it is reserved for acute herniation as a bridge, not prophylactic or prolonged use. Osmotherapy is preferred." },
  { id: "w2-065", domain: "trauma", difficulty: 2, tags: ["Anticoagulation"],
    stem: "A 70-year-old man on apixaban presents with a massive lower GI hemorrhage. He is hypotensive and tachycardic with a markedly dropped hemoglobin. What is the appropriate reversal agent (or alternative if it is unavailable)?",
    options: ["Andexanet alfa (or 4-factor PCC if unavailable)", "Idarucizumab", "Protamine", "Fresh frozen plasma alone"], correctIndex: 0,
    rationale: "Andexanet alfa reverses factor Xa inhibitors (apixaban, rivaroxaban); when unavailable, 4-factor PCC is a reasonable alternative. Idarucizumab is dabigatran-specific." },
  { id: "w2-066", domain: "trauma", difficulty: 2, tags: ["Anticoagulation"],
    stem: "A 66-year-old man on dabigatran for atrial fibrillation presents with a large intracranial hemorrhage and a declining level of consciousness. Which specific reversal agent should be given?",
    options: ["Idarucizumab 5 g IV", "Andexanet alfa", "Protamine", "Vitamin K"], correctIndex: 0,
    rationale: "Idarucizumab (a monoclonal antibody fragment) specifically and rapidly reverses dabigatran. Andexanet is for Xa inhibitors; protamine for heparin; vitamin K for warfarin." },
  { id: "w2-067", domain: "trauma", difficulty: 2, tags: ["Anticoagulation"],
    stem: "An 80-year-old man on rivaroxaban for atrial fibrillation presents with a life-threatening retroperitoneal bleed. He receives a specific factor Xa-inhibitor reversal agent, and the pharmacist reviews its safety profile before administration. The pharmacist notes a boxed warning for thromboembolic/ischemic events and cardiac arrest. Which reversal agent is this?",
    options: ["Andexanet alfa", "Vitamin K", "Protamine", "Idarucizumab"], correctIndex: 0,
    rationale: "Andexanet alfa carries warnings for thromboembolic events, ischemic events, and cardiac arrest; use requires weighing thrombotic risk against benefit in life-threatening Xa-inhibitor bleeding." },
  { id: "w2-068", domain: "trauma", difficulty: 2, tags: ["Anticoagulation"],
    stem: "A 72-year-old woman on therapeutic enoxaparin (last dose 3 hours ago) develops major bleeding. The team requests reversal with protamine and asks about the expected effect. What should you tell them about protamine's effect on enoxaparin?",
    options: ["Reverses ~60% of enoxaparin's anti-Xa activity", "Fully reverses enoxaparin", "Has no effect", "Reverses only the anti-IIa activity fully"], correctIndex: 0,
    rationale: "Protamine incompletely reverses LMWH (neutralizes anti-IIa fully but only ~60% of anti-Xa activity). Dose depends on time since last enoxaparin dose." },
  { id: "w2-069", domain: "trauma", difficulty: 2, tags: ["Anticoagulation"],
    stem: "A normotensive 55-year-old woman has an intermediate-risk (submassive) pulmonary embolism with right-ventricular strain on echocardiography and an elevated troponin. Cardiology weighs catheter-directed versus full-dose systemic thrombolysis. What is the rationale for catheter-directed or reduced-dose therapy here?",
    options: ["Balance clot reduction against systemic bleeding risk", "Guarantee no bleeding", "Avoid anticoagulation", "Replace anticoagulation permanently"], correctIndex: 0,
    rationale: "Catheter-directed or reduced-dose systemic thrombolysis aims to reduce clot burden/RV strain while limiting the major bleeding risk associated with full-dose systemic thrombolysis in intermediate-risk PE." },
  { id: "w2-070", domain: "resp", difficulty: 2, tags: ["Respiratory"],
    stem: "A 30-year-old woman develops anaphylaxis after eating shellfish. She has received two IM epinephrine doses and 2 L of crystalloid but remains hypotensive with persistent wheeze and urticaria. What is the appropriate next step?",
    options: ["IV epinephrine infusion with monitoring", "Oral antihistamines", "Nebulized racemic epinephrine only", "Subcutaneous epinephrine"], correctIndex: 0,
    rationale: "Refractory anaphylaxis (persistent hypotension/airway compromise after repeated IM epinephrine) warrants an IV epinephrine infusion with continuous monitoring; SC route is not recommended due to erratic absorption." },
  { id: "w2-071", domain: "resp", difficulty: 2, tags: ["Respiratory"],
    stem: "A 3-year-old presents with several days of cold symptoms and now has a barky, seal-like cough with inspiratory stridor at rest and suprasternal retractions. Which nebulized medication reduces the upper-airway mucosal edema?",
    options: ["Racemic epinephrine", "Albuterol", "Ipratropium", "Hypertonic saline"], correctIndex: 0,
    rationale: "Nebulized racemic (or L-)epinephrine reduces upper-airway mucosal edema in croup and post-extubation stridor; observe for rebound. Beta-agonists/anticholinergics target lower-airway bronchospasm, not croup." },
  { id: "w2-072", domain: "resp", difficulty: 2, tags: ["Respiratory"],
    stem: "A 35-year-old man in status asthmaticus is tiring, with a silent chest and rising CO2 despite continuous albuterol, ipratropium, IV steroids, and magnesium. He requires intubation. Which induction agent is preferred for its bronchodilating properties?",
    options: ["Ketamine", "Propofol only", "Etomidate", "Midazolam alone"], correctIndex: 0,
    rationale: "Ketamine has bronchodilating properties (and dissociative sedation), making it useful for induction in severe bronchospasm. Volatile anesthetics are another rescue option." },
  { id: "w2-073", domain: "resp", difficulty: 2, tags: ["Respiratory"],
    stem: "A patient with severe upper-airway obstruction and audible stridor is being temporized while the team prepares a definitive airway. A respiratory therapist suggests heliox. How does heliox help in this setting?",
    options: ["Reduces airway resistance by lowering gas density (improving flow)", "Provides bronchodilation directly", "Delivers antibiotics", "Increases oxygen delivery"], correctIndex: 0,
    rationale: "Heliox (helium-oxygen) has lower density than air, reducing turbulent airflow resistance and work of breathing in severe upper airway or asthma obstruction; it is a temporizing adjunct, not a bronchodilator." },
  { id: "w2-074", domain: "endo", difficulty: 2, tags: ["Endocrine"],
    stem: "A 68-year-old man is brought in obtunded. His glucose is markedly elevated with high serum osmolality, profound dehydration, and only trace ketones with a near-normal bicarbonate. How does this presentation differ from DKA?",
    options: ["Higher glucose, higher osmolality, minimal ketosis/acidosis", "Lower glucose", "Severe ketoacidosis", "Normal osmolality"], correctIndex: 0,
    rationale: "HHS features very high glucose (often >600), high serum osmolality, profound dehydration, and minimal ketosis/acidosis. Management emphasizes aggressive fluid resuscitation, then insulin and electrolyte correction." },
  { id: "w2-075", domain: "endo", difficulty: 2, tags: ["Endocrine"],
    stem: "A 52-year-old woman on chronic prednisone for rheumatoid arthritis stopped her steroids two days ago and now presents hypotensive, weak, and confused. She looks to be in crisis. What is the priority medication?",
    options: ["IV hydrocortisone (stress-dose corticosteroids)", "Insulin", "Beta-blocker", "Fludrocortisone alone"], correctIndex: 0,
    rationale: "Adrenal crisis requires immediate IV hydrocortisone (e.g., 100 mg) plus fluid resuscitation and glucose correction. Hydrocortisone provides both glucocorticoid and some mineralocorticoid effect." },
  { id: "w2-076", domain: "endo", difficulty: 2, tags: ["Endocrine"],
    stem: "A 60-year-old man with diabetes becomes unresponsive at home from hypoglycemia. Family and EMS cannot obtain IV access. What should family/EMS administer?",
    options: ["IM/SC glucagon 1 mg", "Oral glucose", "IV insulin", "Sublingual dextrose"], correctIndex: 0,
    rationale: "When IV dextrose can't be given, IM/SC glucagon 1 mg mobilizes hepatic glycogen (less effective in malnourished/alcoholic patients with depleted glycogen). Follow with carbohydrates once alert." },
  { id: "w2-077", domain: "endo", difficulty: 2, tags: ["Endocrine"],
    stem: "A 40-year-old woman in thyroid storm (agitation, fever, tachycardia) is treated with a thionamide and iodine. Beta-blockers are added, and a trainee asks how propranolol helps beyond controlling heart rate. How does propranolol help beyond rate control in thyroid storm?",
    options: ["Control adrenergic symptoms (propranolol also blocks T4-to-T3 conversion)", "Increase thyroid hormone", "Replace thionamides", "Provide sedation"], correctIndex: 0,
    rationale: "Beta-blockers (propranolol) control tachycardia/adrenergic symptoms in thyroid storm; propranolol additionally reduces peripheral T4-to-T3 conversion at high doses. Use cautiously in heart failure." },
  { id: "w2-078", domain: "psych", difficulty: 2, tags: ["Psychiatric"],
    stem: "A 34-year-old woman receives IM olanzapine for severe agitation. Ten minutes later she remains restless, and a nurse asks to add IM lorazepam. What is the concern with combining IM olanzapine and a parenteral benzodiazepine?",
    options: ["Excessive sedation/respiratory and cardiovascular depression", "Serotonin syndrome", "Hyperkalemia", "Nephrotoxicity"], correctIndex: 0,
    rationale: "Concurrent IM olanzapine and parenteral benzodiazepines can cause excessive sedation, hypotension, and respiratory depression; separation or avoidance is advised, especially with alcohol intoxication." },
  { id: "w2-079", domain: "psych", difficulty: 2, tags: ["Psychiatric"],
    stem: "A 45-year-old man on lithium presents confused with a coarse tremor and ataxia. His level is elevated and his creatinine is up from baseline. What is the definitive treatment?",
    options: ["Hemodialysis", "Activated charcoal", "Sodium bicarbonate", "Naloxone"], correctIndex: 0,
    rationale: "Hemodialysis is indicated for severe lithium toxicity (e.g., level >4, or >2.5 with severe symptoms/renal failure). Charcoal does not bind lithium; IV fluids support renal elimination in milder cases." },
  { id: "w2-080", domain: "psych", difficulty: 2, tags: ["Psychiatric"],
    stem: "A 28-year-old man is dangerously agitated ('excited delirium'), combative, and hyperthermic, posing a danger to himself and staff; other agents are impractical and rapid IM control is needed. What is the approximate dissociative IM ketamine dose?",
    options: ["4-5 mg/kg IM", "0.1 mg/kg IM", "20 mg/kg IM", "0.01 mg/kg IM"], correctIndex: 0,
    rationale: "Dissociative-dose ketamine ~4-5 mg/kg IM (or ~1-2 mg/kg IV) rapidly controls severe, dangerous agitation; monitor for airway/respiratory effects, hypersalivation, and laryngospasm." },
  { id: "w2-081", domain: "env", difficulty: 2, tags: ["Environmental"],
    stem: "A 32-year-old man presents with severe generalized muscle rigidity, cramping abdominal pain mimicking an acute abdomen, diaphoresis, and hypertension after a spider bite to the leg. What is appropriate management for severe Latrodectus (black widow) envenomation?",
    options: ["Antivenom plus benzodiazepines/opioids for symptom control", "Crotalidae Fab", "Dantrolene", "Physostigmine"], correctIndex: 0,
    rationale: "Latrodectus (black widow) envenomation causes painful muscle rigidity and autonomic effects; management includes analgesia, benzodiazepines, and antivenom for severe cases. Crotalidae Fab is for pit vipers." },
  { id: "w2-082", domain: "env", difficulty: 2, tags: ["Environmental"],
    stem: "A 22-year-old collapses near the finish line of a summer marathon. He is confused and combative with a very high core temperature. What is the priority intervention?",
    options: ["Rapid cooling (target normothermia); avoid antipyretics", "Acetaminophen", "Dantrolene routinely", "Antibiotics"], correctIndex: 0,
    rationale: "Heat stroke requires immediate active cooling (evaporative, cold-water immersion) to reduce core temperature rapidly; antipyretics are ineffective (the set point is not elevated) and may harm the liver/coagulation." },
  { id: "w2-083", domain: "env", difficulty: 2, tags: ["Environmental"],
    stem: "A 5-year-old in the desert Southwest presents with agitation, roving eye movements, hypersalivation, and muscle twitching after a bark scorpion sting. Which specific therapy may be used for severe neuromuscular symptoms?",
    options: ["Scorpion-specific antivenom (Centruroides immune F(ab')2)", "Crotalidae Fab", "Dantrolene", "Naloxone"], correctIndex: 0,
    rationale: "Severe Centruroides (bark scorpion) envenomation with neuromuscular/autonomic symptoms can be treated with scorpion-specific antivenom, along with benzodiazepines and supportive care." },
  { id: "w2-084", domain: "pain", difficulty: 2, tags: ["Pain"],
    stem: "A 44-year-old man presents with acute severe flank pain radiating to the groin. CT confirms a 4 mm obstructing ureteral stone, and his renal function is normal. Which analgesic approach is often most effective?",
    options: ["An NSAID (e.g., ketorolac) plus an opioid as needed", "Acetaminophen alone", "Antibiotic", "Muscle relaxant alone"], correctIndex: 0,
    rationale: "NSAIDs (ketorolac) reduce ureteral spasm and prostaglandin-mediated pain in renal colic and are often superior to opioids alone; opioids are added for breakthrough pain. Avoid NSAIDs in AKI." },
  { id: "w2-085", domain: "pain", difficulty: 2, tags: ["Pain"],
    stem: "A patient's chart lists a 'fentanyl allergy.' On careful history, the prior reaction was generalized itching and flushing without any airway compromise, hypotension, or rash beyond flushing. What does this most likely represent?",
    options: ["The prior reaction was pruritus/histamine-related, not true allergy", "Never under any circumstances", "Only orally", "With epinephrine pretreatment always"], correctIndex: 0,
    rationale: "Many opioid 'allergies' are non-immune histamine-related effects (itching, flushing). A careful history distinguishes true allergy from predictable side effects, guiding safe opioid selection." },
  { id: "w2-086", domain: "pain", difficulty: 2, tags: ["Pain"],
    stem: "An 82-year-old woman with a displaced hip fracture is in severe pain in the ED. The team wants to minimize systemic opioids given her age and delirium risk. Which regional technique is appropriate to provide analgesia?",
    options: ["Fascia iliaca compartment (nerve) block", "IV lidocaine bolus", "Topical capsaicin", "Oral acetaminophen only"], correctIndex: 0,
    rationale: "A fascia iliaca/femoral nerve block provides targeted analgesia for hip/femur fractures, reducing systemic opioid requirements and associated adverse effects—an increasingly common ED pharmacist-supported intervention." },
  { id: "w2-087", domain: "pain", difficulty: 2, tags: ["Pain"],
    stem: "A patient receiving an IV lidocaine infusion for acute pain develops perioral numbness and tinnitus, then has a generalized seizure. What complication has occurred?",
    options: ["Local anesthetic systemic toxicity (CNS/cardiac) at high levels", "Nephrotoxicity", "Hepatotoxicity", "Hyperkalemia"], correctIndex: 0,
    rationale: "IV lidocaine can cause LAST (perioral numbness, seizures, arrhythmias) at elevated concentrations; use weight-based dosing, monitoring, and avoid in significant hepatic dysfunction/heart block." },
  { id: "w2-088", domain: "special", difficulty: 2, tags: ["Pediatrics"],
    stem: "An 18 kg 4-year-old develops anaphylaxis minutes after a known peanut exposure, with urticaria, wheeze, and vomiting. What is the correct IM epinephrine dose and concentration?",
    options: ["0.01 mg/kg (max 0.3-0.5 mg) of 1 mg/mL", "0.1 mg/kg", "0.01 mg/kg of 0.1 mg/mL", "1 mg fixed"], correctIndex: 0,
    rationale: "Pediatric anaphylaxis epinephrine is 0.01 mg/kg (max 0.3 mg for <25-30 kg using the 0.15 mg autoinjector, up to 0.5 mg) using the 1 mg/mL concentration IM in the anterolateral thigh." },
  { id: "w2-089", domain: "special", difficulty: 2, tags: ["Pediatrics"],
    stem: "A 7-year-old in diabetic ketoacidosis is being resuscitated with fluids and an insulin infusion. The team is vigilant about a specific pediatric complication. What is the most feared complication that dictates cautious fluid and glucose correction in children?",
    options: ["Cerebral edema", "Hyperkalemia", "Hepatic failure", "Pancreatitis"], correctIndex: 0,
    rationale: "Cerebral edema is a devastating complication of pediatric DKA; management emphasizes careful, gradual fluid and glucose correction and vigilance for neurologic deterioration (treat with hypertonic saline/mannitol)." },
  { id: "w2-090", domain: "special", difficulty: 2, tags: ["Pediatrics"],
    stem: "A 5-day-old neonate presents mottled and lethargic with weak pulses and poor perfusion that does not improve after fluid boluses. A ductal-dependent congenital heart lesion is suspected. Which medication maintains ductal patency?",
    options: ["Prostaglandin E1 (alprostadil)", "Indomethacin", "Epinephrine only", "Adenosine"], correctIndex: 0,
    rationale: "Prostaglandin E1 (alprostadil) maintains ductus arteriosus patency in ductal-dependent congenital heart lesions presenting as neonatal shock/cyanosis. Watch for apnea (may need intubation)." },
  { id: "w2-091", domain: "special", difficulty: 2, tags: ["Pediatrics"],
    stem: "A 20-month-old with vomiting needs an antiemetic in the ED. The team reviews which agents are safe at this age. Which agent is contraindicated in this age group due to fatal respiratory-depression risk?",
    options: ["Promethazine", "Ondansetron in standard doses", "Oral rehydration", "Ranitidine"], correctIndex: 0,
    rationale: "Promethazine carries a boxed warning against use in children <2 years due to fatal respiratory depression; it should be avoided in this toddler. Ondansetron at standard weight-based doses, oral rehydration, and ranitidine are not implicated in that risk." },
  { id: "w2-092", domain: "special", difficulty: 2, tags: ["Obstetrics"],
    stem: "A 28-year-old at 34 weeks' gestation with severe preeclampsia is started on a magnesium infusion. Two hours later the nurse reports she can no longer elicit the patellar reflexes. What is the first sign of magnesium toxicity, and what does its loss indicate?",
    options: ["Loss of deep tendon reflexes", "Seizures", "Hypertension", "Tachycardia"], correctIndex: 0,
    rationale: "Magnesium toxicity progresses from loss of deep tendon reflexes, to respiratory depression, to cardiac arrest. Monitor reflexes/respiration; calcium gluconate is the antidote." },
  { id: "w2-093", domain: "special", difficulty: 2, tags: ["Obstetrics"],
    stem: "A 30-year-old woman at 26 weeks' gestation is diagnosed with an acute proximal DVT and requires anticoagulation. The team selects an agent appropriate for pregnancy. Which anticoagulant is preferred in pregnancy?",
    options: ["Low-molecular-weight heparin (does not cross the placenta)", "Warfarin", "A DOAC", "Fondaparinux first-line"], correctIndex: 0,
    rationale: "LMWH is preferred in pregnancy—it doesn't cross the placenta and has predictable dosing. Warfarin is teratogenic; DOAC safety data in pregnancy are lacking." },
  { id: "w2-094", domain: "special", difficulty: 2, tags: ["Obstetrics"],
    stem: "A 33-year-old woman with chronic hypertension has a vaginal delivery complicated by postpartum hemorrhage from uterine atony. Oxytocin has been started and fundal massage performed, but bleeding continues; the team considers an additional uterotonic. Which uterotonic is contraindicated given her blood pressure?",
    options: ["Methylergonovine", "Oxytocin", "Misoprostol", "Carboprost"], correctIndex: 0,
    rationale: "Methylergonovine causes vasoconstriction and can precipitate severe hypertension/stroke; it is avoided in hypertension/preeclampsia. Carboprost's main caution is asthma." },
  { id: "w2-095", domain: "endo", difficulty: 2, tags: ["Electrolytes"],
    stem: "A 55-year-old woman receiving a magnesium infusion for eclampsia was inadvertently over-infused. She is now areflexic and hypotensive with a high magnesium level. What is the appropriate treatment?",
    options: ["IV calcium (antagonizes magnesium's effects)", "More magnesium", "Potassium", "Insulin"], correctIndex: 0,
    rationale: "IV calcium directly antagonizes magnesium's neuromuscular and cardiac effects in symptomatic hypermagnesemia; also stop magnesium sources, give fluids/diuresis, and consider dialysis in renal failure." },
  { id: "w2-096", domain: "endo", difficulty: 2, tags: ["Electrolytes"],
    stem: "A 40-year-old man has refractory hypokalemia; his potassium is not correcting despite repeated IV potassium boluses over several hours. Which coexisting deficiency is likely responsible for the refractory hypokalemia?",
    options: ["Magnesium", "Calcium", "Phosphate", "Sodium"], correctIndex: 0,
    rationale: "Hypomagnesemia promotes renal potassium wasting and makes hypokalemia refractory; correcting magnesium is necessary for effective potassium repletion." },
  { id: "w2-097", domain: "endo", difficulty: 2, tags: ["Electrolytes"],
    stem: "A nurse asks to push 20 mEq of potassium chloride rapidly through a peripheral IV for a symptomatic hypokalemic patient because the oral dose 'isn't working fast enough.' Why must rapid IV potassium administration be avoided?",
    options: ["Cardiac arrhythmia/arrest if infused too fast", "Hypernatremia", "Alkalosis", "Hypocalcemia"], correctIndex: 0,
    rationale: "Peripheral IV potassium is generally limited to ~10 mEq/h (higher rates via central access with monitoring); overly rapid administration can cause fatal arrhythmias. Never give potassium as an IV push." },
  { id: "w2-098", domain: "renal", difficulty: 2, tags: ["Renal"],
    stem: "An anuric hemodialysis-dependent patient presents with a critically high potassium, peaked T waves, and a widening QRS. Calcium and shifting agents (insulin/dextrose, albuterol) are given. After the temporizing measures, what is the definitive therapy?",
    options: ["Emergent hemodialysis (after temporizing measures)", "Sodium polystyrene sulfonate alone", "Oral fluids", "Loop diuretics"], correctIndex: 0,
    rationale: "Anuric/dialysis patients cannot excrete potassium; after calcium and shifting measures (insulin/dextrose, albuterol), emergent hemodialysis definitively removes potassium." },
  { id: "w2-099", domain: "renal", difficulty: 2, tags: ["Renal"],
    stem: "A 30-year-old bodybuilder presents with dark cola-colored urine, diffuse muscle pain, and weakness after an intense workout. His creatine kinase is markedly elevated. What is the most important early intervention?",
    options: ["Aggressive IV isotonic fluid resuscitation", "Loop diuretics first", "Potassium supplementation", "Nephrotoxic contrast"], correctIndex: 0,
    rationale: "Aggressive IV crystalloid hydration prevents pigment-induced AKI in rhabdomyolysis by maintaining renal perfusion and urine output; monitor for hyperkalemia and hypocalcemia. Routine bicarbonate/mannitol is not clearly beneficial." },
  { id: "w2-100", domain: "resus", difficulty: 2, tags: ["Shock"],
    stem: "A 60-year-old man in cardiogenic shock with hypotension needs vasopressor support while awaiting revascularization. The team compares initial pressor options. Which vasopressor is the preferred first-line agent, given its more favorable arrhythmia and mortality profile?",
    options: ["Norepinephrine", "Phenylephrine", "Epinephrine", "Vasopressin alone"], correctIndex: 0,
    rationale: "Norepinephrine is first-line in cardiogenic shock with hypotension (fewer arrhythmias and lower mortality than dopamine in trials). Epinephrine causes more tachyarrhythmias and lactate; phenylephrine (pure alpha) and vasopressin alone don't address low output. An inotrope (dobutamine) is added once perfusion pressure is restored." },
  { id: "w2-101", domain: "resus", difficulty: 2, tags: ["Shock"],
    stem: "A 66-year-old man with vasodilatory shock remains hypotensive despite high-dose norepinephrine and fixed-dose vasopressin. The team considers an additional agent. Which newer vasopressor may be added?",
    options: ["Angiotensin II", "Dobutamine", "Phenylephrine", "Milrinone"], correctIndex: 0,
    rationale: "Angiotensin II is an option for refractory distributive/vasodilatory shock as an add-on when catecholamines and vasopressin are insufficient; monitor for thrombotic risk. Dobutamine and milrinone are inotropes; phenylephrine is a pure alpha-agonist." },
  { id: "w2-102", domain: "resus", difficulty: 2, tags: ["Shock"],
    stem: "A patient develops refractory vasoplegia after cardiac surgery, unresponsive to catecholamines and vasopressin. G6PD status is documented as normal, and methylene blue is added. By what mechanism does methylene blue raise blood pressure?",
    options: ["Inhibits nitric oxide-mediated vasodilation (guanylate cyclase)", "Provides inotropy", "Blocks alpha receptors", "Chelates catecholamines"], correctIndex: 0,
    rationale: "Methylene blue inhibits nitric oxide synthase and guanylate cyclase, reducing NO-mediated vasodilation in refractory vasoplegia (e.g., post-cardiopulmonary bypass, severe sepsis); avoid in G6PD deficiency/serotonergic agents." },
  { id: "w2-103", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "An ED implements barcode medication administration (BCMA). This technology primarily prevents:",
    options: ["Wrong-drug and wrong-patient administration errors", "Prescribing errors", "Diagnostic errors", "Documentation of allergies"], correctIndex: 0,
    rationale: "BCMA verifies the 'rights' at the point of care, reducing wrong-drug, wrong-dose, and wrong-patient administration errors. It does not address upstream prescribing errors." },
  { id: "w2-104", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "A 'just culture' approach to a medication error focuses on:",
    options: ["Distinguishing human error, at-risk behavior, and reckless behavior—not blaming individuals for system failures", "Punishing all errors equally", "Ignoring errors", "Hiding errors from staff"], correctIndex: 0,
    rationale: "Just culture balances accountability and learning: console human error, coach at-risk behavior, and discipline only reckless behavior—encouraging reporting and system improvement." },
  { id: "w2-105", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "Which is an example of a 'forcing function' preventing a wrong-route error?",
    options: ["Oral syringes that cannot connect to IV tubing", "A warning label", "Staff education", "A double check"], correctIndex: 0,
    rationale: "Oral (ENFit/non-Luer) syringes physically cannot connect to IV lines—a forcing function that makes the wrong-route error impossible, ranking high on the hierarchy of effectiveness." },
  { id: "w2-106", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "Concentrated electrolytes (e.g., potassium chloride vials) on ED floor stock are a hazard; ISMP recommends:",
    options: ["Removing concentrated KCl from floor stock / using premixed solutions", "Storing them with saline flushes", "Wider availability", "No restrictions"], correctIndex: 0,
    rationale: "ISMP recommends removing concentrated potassium chloride from patient-care areas and using commercially premixed solutions to prevent fatal accidental IV bolus administration." },
  { id: "w2-107", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "Which technology reduces IV infusion pump programming errors?",
    options: ["Smart pumps with dose-error-reduction software (DERS)", "Standard gravity tubing", "Manual calculation", "Paper charts"], correctIndex: 0,
    rationale: "Smart infusion pumps with DERS ('guardrails') alert when programmed doses fall outside preset limits, reducing infusion errors—especially valuable for high-alert medications." },
  { id: "w2-108", domain: "pmr", difficulty: 2, tags: ["Regulatory"],
    stem: "Under the Controlled Substances Act, which schedule has the highest potential for abuse with no accepted medical use?",
    options: ["Schedule I", "Schedule II", "Schedule IV", "Schedule V"], correctIndex: 0,
    rationale: "Schedule I substances (e.g., heroin, LSD) have high abuse potential and no accepted medical use. Schedule II (e.g., fentanyl, oxycodone) have accepted medical uses with high abuse potential." },
  { id: "w2-109", domain: "pmr", difficulty: 2, tags: ["Regulatory"],
    stem: "A pharmacist observing a colleague diverting controlled substances should:",
    options: ["Report per institutional and DEA/regulatory requirements", "Ignore it", "Confront and handle privately only", "Wait for more evidence indefinitely"], correctIndex: 0,
    rationale: "Suspected diversion must be reported through institutional channels and to appropriate regulatory bodies (state board, DEA) per policy; drug diversion is a patient-safety and legal issue." },
  { id: "w2-110", domain: "pmr", difficulty: 2, tags: ["Emergency Prep"],
    stem: "During a radiological emergency with internal cesium-137 contamination, the appropriate decorporation agent is:",
    options: ["Prussian blue", "Potassium iodide", "Calcium-DTPA", "Deferoxamine"], correctIndex: 0,
    rationale: "Prussian blue enhances fecal elimination of cesium/thallium. Potassium iodide protects the thyroid from radioiodine; Ca/Zn-DTPA is for plutonium/americium/curium." },
  { id: "w2-111", domain: "pmr", difficulty: 2, tags: ["Emergency Prep"],
    stem: "Potassium iodide (KI) in a nuclear release is used to:",
    options: ["Block thyroid uptake of radioactive iodine", "Treat cesium contamination", "Reverse radiation burns", "Chelate plutonium"], correctIndex: 0,
    rationale: "KI saturates the thyroid with stable iodine, blocking uptake of radioactive iodine-131 and reducing thyroid cancer risk—most effective when given before or shortly after exposure, especially in children." },
  { id: "w2-112", domain: "pmr", difficulty: 2, tags: ["Emergency Prep"],
    stem: "In a mass-casualty opioid overdose event, the pharmacist ensures adequate stock of:",
    options: ["Naloxone (including intranasal formulations)", "Flumazenil", "Atropine", "Physostigmine"], correctIndex: 0,
    rationale: "Naloxone (IV/IM/intranasal) is essential for opioid mass-exposure events; pharmacists coordinate supply, distribution, and dosing guidance including the potential need for higher/repeat doses with potent synthetic opioids." },
  { id: "w2-113", domain: "id", difficulty: 2, tags: ["Stewardship"],
    stem: "An ED antimicrobial stewardship intervention to reduce inappropriate fluoroquinolone use would be:",
    options: ["Prospective audit/feedback and order-set defaults favoring narrower agents", "Removing all antibiotics", "Mandating broad-spectrum use", "No intervention"], correctIndex: 0,
    rationale: "Effective stewardship uses prospective audit and feedback, guideline-based order sets, and formulary/default nudges to steer prescribing toward appropriate, narrower-spectrum agents and reduce resistance/adverse effects." },
  { id: "w2-114", domain: "id", difficulty: 2, tags: ["Stewardship"],
    stem: "A rapid diagnostic test identifying MRSA vs MSSA in blood allows the pharmacist to:",
    options: ["De-escalate or optimize therapy sooner (e.g., stop vancomycin for MSSA)", "Ignore culture data", "Broaden coverage unnecessarily", "Delay all therapy"], correctIndex: 0,
    rationale: "Rapid molecular diagnostics paired with pharmacist-driven stewardship enable faster de-escalation/optimization (e.g., switching MSSA bacteremia to cefazolin/nafcillin), improving outcomes and reducing unnecessary broad-spectrum use." },
  { id: "w2-115", domain: "safety", difficulty: 2, tags: ["Formulary"],
    stem: "When a P&T committee evaluates adding a new expensive reversal agent, the pharmacist should present:",
    options: ["Comparative efficacy, safety, cost, and place in therapy vs. alternatives", "Only the drug's marketing materials", "Cost alone", "Prescriber anecdotes only"], correctIndex: 0,
    rationale: "Formulary decisions require an objective evaluation of comparative efficacy, safety, cost-effectiveness, and therapeutic role relative to existing options, informing evidence-based inclusion criteria." },
  { id: "w2-116", domain: "safety", difficulty: 2, tags: ["Quality"],
    stem: "A sentinel event is best defined as:",
    options: ["An unexpected occurrence involving death or serious harm (or risk thereof)", "Any medication error", "A near-miss", "A billing discrepancy"], correctIndex: 0,
    rationale: "A sentinel event is a patient-safety event resulting in death, permanent harm, or severe temporary harm (or the risk of such), warranting immediate investigation and response (e.g., RCA)." },
  { id: "w2-117", domain: "safety", difficulty: 2, tags: ["Quality"],
    stem: "To measure the impact of a new ED sepsis bundle, an appropriate process metric is:",
    options: ["Time from triage to antibiotic administration", "Total pharmacy revenue", "Number of staff", "Bed occupancy alone"], correctIndex: 0,
    rationale: "Time-to-antibiotics is a meaningful process measure linked to sepsis outcomes; process and outcome metrics (mortality, length of stay) together evaluate bundle effectiveness." },
  { id: "w2-118", domain: "pmr", difficulty: 2, tags: ["CPA"],
    stem: "State-specific scope of practice determines whether an ED pharmacist can:",
    options: ["Independently order labs, adjust doses, or initiate therapy under protocol", "Perform surgery", "Diagnose independently in all states", "Practice without any regulation"], correctIndex: 0,
    rationale: "Pharmacist scope (including CPAs and protocol-based functions like reactive dosing, lab ordering, therapy initiation) is defined by state law and institutional agreements and varies by jurisdiction." },
  { id: "w2-119", domain: "safety", difficulty: 2, tags: ["Transitions"],
    stem: "At ED discharge on a new anticoagulant, the pharmacist's counseling should emphasize:",
    options: ["Adherence, bleeding warning signs, and follow-up/monitoring", "Only the cost", "Nothing, since it's short-term", "To stop if any bruising"], correctIndex: 0,
    rationale: "Anticoagulant discharge counseling should cover adherence, recognizing bleeding, interactions, dietary/monitoring needs (if applicable), and follow-up—reducing readmissions and adverse events." },
  { id: "w2-120", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "An ED 'medication reconciliation' finds a patient is on a duplicate anticoagulant. This is an example of preventing:",
    options: ["An adverse drug event from therapeutic duplication", "A diagnostic error", "A billing error", "A staffing issue"], correctIndex: 0,
    rationale: "Identifying therapeutic duplication (e.g., a DOAC plus warfarin) during reconciliation prevents a serious adverse drug event—an important pharmacist safety function at transitions of care." },
  { id: "w2-121", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "To reduce errors with weight-based dosing in pediatrics, the ED should:",
    options: ["Record weight in kilograms only (never pounds) and use it for all dosing", "Allow pounds or kilograms", "Estimate weight always", "Use adult doses scaled by age"], correctIndex: 0,
    rationale: "Recording pediatric weight in kilograms only (never pounds) and using it consistently for all calculations prevents ~2.2-fold dosing errors—a key ISMP recommendation." },
  { id: "w2-122", domain: "pmr", difficulty: 2, tags: ["Regulatory"],
    stem: "The 'five rights' of medication administration include right patient, drug, dose, route, and:",
    options: ["Time", "Cost", "Manufacturer", "Color"], correctIndex: 0,
    rationale: "The classic five rights are right patient, drug, dose, route, and time (with expanded rights including documentation and indication). They guide safe administration but rely on individual vigilance." },
  { id: "w2-123", domain: "pmr", difficulty: 2, tags: ["Advocacy"],
    stem: "To secure funding for a dedicated ED pharmacist during peak hours, the strongest argument is:",
    options: ["Documented improvements in time-critical care and cost avoidance", "Personal preference", "Comparison to other hospitals only", "The pharmacist's seniority"], correctIndex: 0,
    rationale: "Demonstrating value through outcome data—reduced time to critical therapies (thrombolytics, antibiotics), intercepted errors, and cost avoidance—provides the strongest case for resource allocation." },
  { id: "w2-124", domain: "safety", difficulty: 2, tags: ["Med Safety"],
    stem: "An override report shows frequent ADC removal of a paralytic without pharmacist verification. The safest response is:",
    options: ["Restrict the paralytic to override only in true emergencies and add safeguards (e.g., warnings, sequestration)", "Remove all paralytics", "Do nothing", "Increase override access"], correctIndex: 0,
    rationale: "Neuromuscular blockers are high-alert; frequent overrides are dangerous. Restricting access, adding warnings/auxiliary labels, and requiring verification where feasible reduce catastrophic paralysis-without-ventilation errors." },
  { id: "w2-125", domain: "safety", difficulty: 2, tags: ["Quality"],
    stem: "When trending ED medication errors over time, a run chart or control chart helps:",
    options: ["Distinguish common-cause variation from special-cause (real) changes", "Assign individual blame", "Calculate drug costs", "Determine staffing ratios"], correctIndex: 0,
    rationale: "Statistical process control (run/control charts) differentiates normal (common-cause) variation from meaningful (special-cause) shifts, guiding whether an intervention truly changed performance." },
  { id: "w2-126", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A diagnostic test has high sensitivity. A negative result is therefore useful to:",
    options: ["Rule out disease (SnNout)", "Rule in disease", "Confirm disease", "Determine prevalence"], correctIndex: 0,
    rationale: "A highly Sensitive test with a Negative result rules OUT disease (SnNout). A highly Specific test with a Positive result rules IN disease (SpPin)." },
  { id: "w2-127", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "The positive predictive value of a test:",
    options: ["Depends on disease prevalence in the population", "Is independent of prevalence", "Equals sensitivity", "Is fixed for a test"], correctIndex: 0,
    rationale: "PPV (and NPV) vary with disease prevalence: as prevalence falls, PPV decreases even for a good test. Sensitivity and specificity are intrinsic test properties independent of prevalence." },
  { id: "w2-128", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "An odds ratio is the appropriate effect measure for which study design?",
    options: ["Case-control study", "Prospective cohort", "Randomized trial", "Cross-over trial"], correctIndex: 0,
    rationale: "Case-control studies (which sample by outcome) use odds ratios because incidence/risk cannot be directly calculated. Cohort studies and RCTs can compute relative risk." },
  { id: "w2-129", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A confidence interval that is very wide most likely reflects:",
    options: ["A small sample size / imprecise estimate", "A large effect", "No variability", "Statistical significance"], correctIndex: 0,
    rationale: "Wide confidence intervals indicate imprecision, often from small sample sizes or high variability. Narrow intervals reflect more precise estimates (larger samples)." },
  { id: "w2-130", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "Which analysis is appropriate for comparing survival curves between two groups over time?",
    options: ["Log-rank test / Kaplan-Meier analysis", "Chi-square only", "Paired t-test", "Pearson correlation"], correctIndex: 0,
    rationale: "Kaplan-Meier curves display survival over time and the log-rank test compares them; Cox proportional hazards models estimate hazard ratios while adjusting for covariates." },
  { id: "w2-131", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A study reports the result was 'statistically significant but not clinically significant.' This means:",
    options: ["The effect is real but too small to matter to patients", "The study was flawed", "The p-value was >0.05", "The effect is large"], correctIndex: 0,
    rationale: "Statistical significance (p<0.05) can occur with trivial effect sizes, especially in large trials. Clinical significance considers whether the magnitude of effect is meaningful to patients." },
  { id: "w2-132", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "Confounding occurs when:",
    options: ["A third variable is associated with both exposure and outcome, distorting the association", "The sample is too small", "Randomization is used", "Blinding fails"], correctIndex: 0,
    rationale: "A confounder is associated with both the exposure and outcome and is not on the causal pathway, biasing the observed association. Randomization and statistical adjustment address confounding." },
  { id: "w2-133", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A number needed to harm (NNH) of 50 means:",
    options: ["1 additional patient is harmed for every 50 treated", "50 patients are harmed", "The drug is safe", "The treatment benefits 50 patients"], correctIndex: 0,
    rationale: "NNH = 1/absolute risk increase; an NNH of 50 means for every 50 patients treated, 1 additional adverse event occurs compared to control. Compare NNT vs NNH to weigh benefit/risk." },
  { id: "w2-134", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "Blinding in a trial primarily reduces:",
    options: ["Detection/performance/ascertainment bias", "Confounding", "Selection bias", "Type I error"], correctIndex: 0,
    rationale: "Blinding (of patients, providers, assessors) reduces performance and detection/ascertainment bias. Randomization addresses confounding; allocation concealment reduces selection bias." },
  { id: "w2-135", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A composite endpoint (e.g., death, MI, or stroke) should be interpreted cautiously because:",
    options: ["The overall result may be driven by the least important or most frequent component", "It is always more valid", "It reduces sample size needs without tradeoffs", "Components are always equally weighted"], correctIndex: 0,
    rationale: "Composite endpoints can be misleading if driven by a less patient-important or 'softer' component (e.g., revascularization) rather than hard outcomes (death). Examine individual components." },
  { id: "w2-136", domain: "pmr", difficulty: 2, tags: ["Literature"],
    stem: "Publication bias refers to the tendency for:",
    options: ["Positive/significant studies to be published more than negative ones", "Only large studies to be published", "Random publication", "All studies being published equally"], correctIndex: 0,
    rationale: "Publication bias skews the literature because studies with positive/significant findings are more likely to be published, inflating apparent treatment effects. Funnel plots help detect it in meta-analyses." },
  { id: "w2-137", domain: "pmr", difficulty: 2, tags: ["Education"],
    stem: "Adult learning theory (andragogy) suggests ED staff education is most effective when it is:",
    options: ["Problem-centered, relevant, and applicable to their practice", "Purely lecture-based", "Abstract and theoretical", "Disconnected from clinical work"], correctIndex: 0,
    rationale: "Adult learners are motivated by relevance and problem-solving; case-based, practice-applicable education (e.g., real ED scenarios) is more effective than abstract lectures." },
  { id: "w2-138", domain: "pmr", difficulty: 2, tags: ["Education"],
    stem: "When delivering a journal club critique, the pharmacist should primarily evaluate:",
    options: ["Internal validity, external validity (generalizability), and clinical applicability", "The authors' reputations", "The journal's cover", "Only the abstract"], correctIndex: 0,
    rationale: "Critical appraisal assesses internal validity (methodology, bias), external validity (generalizability to your patients), and applicability/impact on practice—not surface features." },
  { id: "w2-139", domain: "pmr", difficulty: 2, tags: ["Literature"],
    stem: "The hierarchy of evidence generally places which at the top for therapeutic questions?",
    options: ["Systematic reviews/meta-analyses of RCTs", "Expert opinion", "Case reports", "Animal studies"], correctIndex: 0,
    rationale: "For therapy questions, well-conducted systematic reviews/meta-analyses of RCTs (and large high-quality RCTs) sit atop the evidence hierarchy; expert opinion and case reports are lowest." },
  { id: "w2-140", domain: "pmr", difficulty: 2, tags: ["Biostatistics"],
    stem: "A relative risk of 1.0 indicates:",
    options: ["No difference in risk between groups", "Doubled risk", "Halved risk", "Statistical significance"], correctIndex: 0,
    rationale: "An RR (or OR/HR) of 1.0 means no difference between groups. Values >1 indicate increased risk/hazard; <1 indicate reduced risk. Significance depends on the confidence interval." },
  { id: "w2-141", domain: "gi", difficulty: 2, tags: ["GI Emergencies"],
    stem: "A 55-year-old man with cirrhosis presents vomiting bright red blood. He is hypotensive and tachycardic, and known esophageal varices are the suspected source. Blood products and urgent endoscopy are arranged. In addition to blood products and endoscopy, which pharmacologic agent reduces portal pressure?",
    options: ["Octreotide infusion", "Norepinephrine", "Vasopressin bolus alone", "Metoclopramide"], correctIndex: 0,
    rationale: "Octreotide (a somatostatin analog) reduces splanchnic blood flow and portal pressure in variceal bleeding. Combine with endoscopy and prophylactic antibiotics (e.g., ceftriaxone) which reduce mortality in cirrhotic GI bleed." },
  { id: "w2-142", domain: "gi", difficulty: 2, tags: ["GI Emergencies"],
    stem: "A 62-year-old man with a bleeding gastric ulcer undergoes endoscopy; a visible vessel is clipped. The GI team asks about IV pharmacotherapy to reduce rebleeding. Which IV medication stabilizes the clot and reduces rebleeding?",
    options: ["High-dose proton pump inhibitor (e.g., pantoprazole)", "H2 blocker only", "Sucralfate IV", "Antacids"], correctIndex: 0,
    rationale: "IV proton pump inhibitors raise gastric pH, stabilizing clot formation over ulcers and reducing rebleeding after endoscopic hemostasis. A bolus followed by infusion (or intermittent high-dose) is used." },
  { id: "w2-143", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 30-year-old woman presents with fever, diffuse macular erythroderma, hypotension, and early desquamation; toxic shock syndrome is suspected. Broad antibiotics are started. Beyond broad coverage, which agent is added for toxin suppression?",
    options: ["Clindamycin (toxin suppression) plus a beta-lactam/vancomycin", "A cephalosporin alone", "Metronidazole alone", "An antifungal"], correctIndex: 0,
    rationale: "Toxic shock syndrome management adds clindamycin (or linezolid) to suppress toxin production via ribosomal inhibition, combined with broad coverage (vancomycin + beta-lactam) and source control; IVIG may be considered." },
  { id: "w2-144", domain: "id", difficulty: 2, tags: ["Antimicrobials"],
    stem: "A 55-year-old man with febrile neutropenia (ANC 100) remains febrile after 5 days of appropriate broad-spectrum antibacterial therapy, with no source identified. What should be added empirically at this point?",
    options: ["Empiric antifungal therapy", "Another gram-positive agent", "Oral antibiotics", "Antivirals routinely"], correctIndex: 0,
    rationale: "Persistent fever in neutropenia despite broad antibacterial coverage warrants empiric antifungal therapy (e.g., an echinocandin or liposomal amphotericin) given invasive fungal infection risk." },
  { id: "w2-145", domain: "cv", difficulty: 2, tags: ["Cardiology"],
    stem: "A 68-year-old man presents with sudden tearing chest pain radiating to the back. Blood pressure is markedly elevated with a differential between arms, and chest imaging shows a widened mediastinum concerning for aortic dissection. What is the correct sequence of blood-pressure and heart-rate control?",
    options: ["An IV beta-blocker (esmolol/labetalol) first, then a vasodilator if needed", "A vasodilator alone", "Hydralazine alone", "No treatment until surgery"], correctIndex: 0,
    rationale: "In aortic dissection, reduce shear stress (dP/dt): give a beta-blocker (esmolol/labetalol) to control HR (<60) BEFORE adding a vasodilator, which alone would cause reflex tachycardia and worsen dissection. Target SBP ~100-120." },
  { id: "w2-146", domain: "cv", difficulty: 2, tags: ["Cardiology"],
    stem: "A patient in hypertensive emergency with acute pulmonary edema needs smooth, titratable blood-pressure control. The team compares clevidipine and nicardipine with nitroprusside. Why are clevidipine and nicardipine well suited compared with nitroprusside?",
    options: ["Are titratable IV calcium channel blockers with rapid, predictable control", "Are oral only", "Cause reflex bradycardia", "Have no monitoring needs"], correctIndex: 0,
    rationale: "Clevidipine (ultra-short-acting) and nicardipine are titratable IV dihydropyridine calcium channel blockers providing smooth, predictable BP control in hypertensive emergencies, avoiding the cyanide risk of nitroprusside." },
  { id: "w2-147", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A patient on a prolonged high-dose nitroprusside infusion (now day 3) with renal impairment develops altered mental status and a rising lactic acidosis. What toxicity should you suspect?",
    options: ["Cyanide/thiocyanate toxicity", "Hyperkalemia", "Hypoglycemia", "Serotonin syndrome"], correctIndex: 0,
    rationale: "Prolonged/high-dose nitroprusside can cause cyanide and thiocyanate accumulation (especially in renal/hepatic impairment), presenting with acidosis and altered mentation. Treat with hydroxocobalamin/sodium thiosulfate and stop the drug." },
  { id: "w2-148", domain: "tox", difficulty: 2, tags: ["Toxicology"],
    stem: "A 27-year-old 'body stuffer' who swallowed cocaine packets presents agitated, hypertensive, and tachycardic with chest discomfort. What is the first-line pharmacologic treatment?",
    options: ["Benzodiazepines (avoid beta-blockers)", "Non-selective beta-blockers", "Haloperidol", "Physostigmine"], correctIndex: 0,
    rationale: "Benzodiazepines are first-line for cocaine/sympathomimetic toxicity (agitation, hypertension, tachycardia). Non-selective beta-blockers risk unopposed alpha stimulation; use nitrates/phentolamine/calcium channel blockers for refractory hypertension." },
  { id: "w2-149", domain: "resp", difficulty: 2, tags: ["Allergic"],
    stem: "A 40-year-old with documented ceftriaxone anaphylaxis presents with fever, headache, neck stiffness, and photophobia; bacterial meningitis is suspected and empiric therapy is urgent. Which approach best provides gram-negative CNS coverage while minimizing cross-reactivity?",
    options: ["Aztreonam-based regimen (with vancomycin +/- alternatives)", "Another cephalosporin", "A carbapenem without caution", "Ampicillin alone"], correctIndex: 0,
    rationale: "With a true cephalosporin anaphylaxis, aztreonam has minimal cross-reactivity (except ceftazidime side chain) and can provide gram-negative CNS coverage; add agents for gram-positives/Listeria as indicated. Carbapenems have low but nonzero cross-reactivity." },
  { id: "w2-150", domain: "neuro", difficulty: 2, tags: ["Neuro"],
    stem: "A 55-year-old with myasthenia gravis in crisis develops pneumonia and worsening respiratory muscle weakness. The team reviews which antibiotics to avoid. Which antibiotic class can worsen neuromuscular weakness and should be avoided?",
    options: ["Aminoglycosides (and fluoroquinolones, macrolides)", "Cephalosporins", "Penicillins", "Nitrofurantoin"], correctIndex: 0,
    rationale: "Aminoglycosides, fluoroquinolones, and macrolides can worsen neuromuscular blockade in myasthenia gravis, precipitating or worsening crisis; they should be avoided. Treatment includes IVIG/plasmapheresis and respiratory support." }
];
